#include <stdio.h>
#include <string.h>

#define MAX_STACK 1024

int is_balanced(const char *s) {
    char stack[MAX_STACK];
    int top = -1;
    size_t len = strlen(s);

    for (size_t i = 0; i < len; ++i) {
        char c = s[i];
        switch (c) {
            case '(':
            case '[':
            case '{':
                if (top + 1 >= MAX_STACK) return 0; /* stack overflow */
                stack[++top] = c;
                break;
            case ')':
                if (top < 0 || stack[top--] != '(') return 0;
                break;
            case ']':
                if (top < 0 || stack[top--] != '[') return 0;
                break;
            case '}':
                if (top < 0 || stack[top--] != '{') return 0;
                break;
            default:
                /* ignore any other characters */
                break;
        }
    }
    return top == -1;
}

/* Explanation: The fixed-size stack limits the function to strings
   whose bracket depth never exceeds MAX_STACK (1024); deeper nesting
   or longer strings cause an immediate return of 0. */
